// Media for blog posts: cover loops, explainer films, illustrations and read-aloud narration.
// Generated by scripts/blog-media/make.py into src/blog/media/manifest.json (small files live in public/media/blog/<slug>/,
// long videos and narration audio are GitHub Release assets under the media-v1 tag).
import manifest from './manifest.json'

export interface Chapter { t: number; label: string }
export interface PostImage { src: string; alt: string; caption: string; after?: number | 'end'; heading?: string }
export interface NeuralVoice { id: string; label: string; gender: string; accent: string; dur: number; words: number; mp3: number | null }
export interface PostMedia {
  hash?: string | null
  loop?: boolean
  video?: { dur: number; chapters: Chapter[]; mp4: number; webm: number }
  images?: PostImage[]
  voices?: NeuralVoice[]
}

const M = manifest as unknown as { release: string; posts: Record<string, PostMedia> }
const base = import.meta.env.BASE_URL

export const mediaFor = (slug: string): PostMedia => M.posts[slug] ?? {}
export const pub = (slug: string, file: string) => `${base}media/blog/${slug}/${file}`
export const rel = (file: string) => M.release + file

export const loopSources = (slug: string) => [
  { src: pub(slug, 'loop.webm'), type: 'video/webm; codecs="av01.0.05M.08"' },
  { src: pub(slug, 'loop.mp4'), type: 'video/mp4' },
]
export const videoSources = (slug: string) => [
  { src: rel(`${slug}.webm`), type: 'video/webm; codecs="av01.0.08M.08, opus"' },
  { src: rel(`${slug}.mp4`), type: 'video/mp4' },
]
export function audioUrl(slug: string, voice: string) {
  const a = typeof document !== 'undefined' ? document.createElement('audio') : null
  const opus = a && (a.canPlayType('audio/ogg; codecs="opus"') === 'probably' || a.canPlayType('audio/ogg; codecs=opus') !== '')
  return rel(`${slug}-${voice}.${opus ? 'opus' : 'mp3'}`)
}
export const mp3Url = (slug: string, voice: string) => rel(`${slug}-${voice}.mp3`)
export const timingsUrl = (slug: string, voice: string) => pub(slug, `read-${voice}.json`)

/** Minutes of listening for the default narration, or an estimate from the reading time */
export function listenMinutes(slug: string, readMinutes: number) {
  const v = mediaFor(slug).voices?.[0]
  return v ? Math.max(1, Math.round(v.dur / 60)) : Math.round(readMinutes * 1.25)
}

export const fmtTime = (s: number) => {
  if (!isFinite(s) || s < 0) s = 0
  const m = Math.floor(s / 60), r = Math.floor(s % 60)
  return `${m}:${r.toString().padStart(2, '0')}`
}

export const prefersReducedMotion = () => typeof matchMedia !== 'undefined' && matchMedia('(prefers-reduced-motion: reduce)').matches
